<script setup>
import {ref} from 'vue'

import {parseCurl} from './curlImport.js'
const props=defineProps({disabled:Boolean}),emit=defineEmits(['import'])
const open=ref(false),text=ref(''),preview=ref(null),error=ref('')
function parse(){try{preview.value=parseCurl(text.value);error.value=''}catch(e){preview.value=null;error.value=e.message}}
function apply(){if(!preview.value)return false;emit('import',preview.value.request);open.value=false;text.value='';preview.value=null;return true}



import {Badge,Button,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Field,FieldDescription,FieldError,FieldLabel,Textarea} from '../shared/shadcn-ui.js'
</script>
<template><Button @click="open=true" variant="outline" size="default" type="button" :disabled="(disabled)">导入 cURL</Button><Dialog :open="open" @update:open="async v=>{if(!v){open=false;}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (760)==='number'?(760)+'px':(760)}" :show-close-button="true" @interact-outside="e=>{if(!(false))e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>导入 cURL 请求</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><fieldset class="min-w-0 space-y-5" ><Field><FieldLabel>粘贴 cURL</FieldLabel><Textarea v-model="text" aria-label="cURL 命令" @input="preview=null" :rows="({minRows:6,maxRows:14}).minRows||4"/><FieldError v-if="error||'仅解析请求，不执行命令；发送地址仍由当前应用环境决定。'">{{error||'仅解析请求，不执行命令；发送地址仍由当前应用环境决定。'}}</FieldError></Field></fieldset><template v-if="preview"><dl bordered class="grid min-w-0 gap-4 sm:grid-cols-2"><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">原始主机</dt><dd class="min-w-0 break-words">{{preview.origin}}（仅供核对，不会改写环境配置）</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">请求</dt><dd class="min-w-0 break-words">{{preview.request.method}} {{preview.request.path}}</dd></div><div class="min-w-0 space-y-1"><dt class="text-sm text-muted-foreground">正文</dt><dd class="min-w-0 break-words">{{preview.request.body_type||'原始正文'}} · {{preview.request.mode==='sse'?'SSE':'HTTP'}}</dd></div></dl><div style="margin-top:12px" class="flex flex-wrap items-center gap-2"><Badge v-for="warning in preview.warnings" :key="warning" style="white-space:normal;height:auto" :variant="(&quot;orange&quot;)==='red'?'destructive':'secondary'">{{warning}}</Badge></div></template></div><DialogFooter><Button @click="open=false" variant="outline" size="default" type="button">取消</Button><Button v-if="!preview" @click="parse" variant="default" size="default" type="button">预览请求</Button><Button v-else @click="apply" variant="default" size="default" type="button">替换当前请求草稿</Button></DialogFooter></DialogContent></Dialog></template>
